;;; NSS instruments and macros
;;; generated by furtool.py (ngdevkit)
;;; ---
;;; Song title: ngdevkit eye catcher theme
;;; Song author: Damien Ciabrini
;;;

        .area   CODE

        ;; offset of ADPCM samples in ROMs
        .include "samples.inc"

instruments_ngdevkit::
        .dw     instr_00_instrument_0
        .dw     instr_01_instrument_1
        .dw     instr_02_instrument_2
        .dw     macro_03_instrument_3

instr_00_instrument_0:
        ;;       OP1 - OP3 - OP2 - OP4
        .db     0x01, 0x01, 0x01, 0x01   ; DT | MUL
        .db     0x0d, 0x0d, 0x0d, 0x0d   ; TL
        .db     0x1a, 0x1a, 0x1a, 0x1a   ; KS | AR
        .db     0x08, 0x08, 0x08, 0x08   ; AM | DR
        .db     0x43, 0x43, 0x43, 0x43   ; SR
        .db     0x85, 0x85, 0x85, 0x85   ; SL | RR
        .db     0x00, 0x00, 0x00, 0x00   ; SSG
        .db     0x17                     ; FB | ALGO
        .db     0xc0                     ; LR | AMS | FMS
        .db     0x0d, 0x0d, 0x0d, 0x0d   ; TL

instr_01_instrument_1:
        ;;       OP1 - OP3 - OP2 - OP4
        .db     0x25, 0x21, 0x71, 0x01   ; DT | MUL
        .db     0x7f, 0x7f, 0x7f, 0x0c   ; TL
        .db     0x1f, 0x1f, 0x1f, 0x1a   ; KS | AR
        .db     0x08, 0x04, 0x0a, 0x08   ; AM | DR
        .db     0x40, 0x40, 0x40, 0x43   ; SR
        .db     0xff, 0xb1, 0xf4, 0x85   ; SL | RR
        .db     0x00, 0x00, 0x00, 0x00   ; SSG
        .db     0x27                     ; FB | ALGO
        .db     0xc0                     ; LR | AMS | FMS
        .db     0x7f, 0x7f, 0x7f, 0x0c   ; TL

instr_02_instrument_2:
        ;;       OP1 - OP3 - OP2 - OP4
        .db     0x02, 0x63, 0x23, 0x61   ; DT | MUL
        .db     0x1a, 0x32, 0x00, 0x00   ; TL
        .db     0x18, 0x11, 0x19, 0x19   ; KS | AR
        .db     0x0a, 0x06, 0x11, 0x18   ; AM | DR
        .db     0x48, 0x4d, 0x49, 0x5b   ; SR
        .db     0x0a, 0x19, 0x64, 0x69   ; SL | RR
        .db     0x00, 0x00, 0x00, 0x07   ; SSG
        .db     0x0c                     ; FB | ALGO
        .db     0xc0                     ; LR | AMS | FMS
        .db     0x1a, 0x32, 0x00, 0x00   ; TL

macro_03_instrument_3:
        ;; macro load function
        .dw     macro_03_load_func
        ;; macro actions
        .db     0x00, 0x08, 0x02, 0x08, 0x00, 0x08, 0xff, 0x3a   ; tick 0
        .db     0x03, 0x06, 0xff, 0x0a                           ; tick 1
        .db     0x03, 0x06, 0xff, 0x0a                           ; tick 2
        .db     0x03, 0x05, 0xff, 0x0a                           ; tick 3
        .db     0x03, 0x04, 0xff, 0x0a                           ; tick 4
        .db     0x03, 0x04, 0xff, 0x0a                           ; tick 5
        .db     0x03, 0x03, 0xff, 0x0a                           ; tick 6
        .db     0x03, 0x02, 0xff, 0x0a                           ; tick 7
        .db     0x03, 0x02, 0xff, 0x0a                           ; tick 8
        .db     0x03, 0x01, 0xff, 0x08                           ; tick 9
        .db     0xff                                             ; end
        .dw     0x0000                                           ; no loop

macro_03_load_func:
        ld      bc, #3
        add     hl, bc
        set     4, (ix)
        ret

